// Definition for the clock gating cell CLKGATETST_X1
// This implements a glitch-free clock gate using an enable latch.
// The latch samples the combined enable (E | SE) when the clock (CK) is low.
// The gated clock (GCK) is then generated by ANDing CK with the latched enable.
module CLKGATETST_X1 (
    input CK,
    input E,
    input SE,
    output GCK
);

    wire combined_enable = E | SE;
    reg  latch_q; // Output of the enable latch

    // Enable latch: transparent when CK is low, holding its value when CK is high.
    // This ensures that the enable signal (latch_q) is stable when CK transitions high,
    // preventing glitches on GCK.
    always @(*) begin
        if (!CK) begin // When clock (CK) is low, latch_q tracks combined_enable
            latch_q = combined_enable;
        end
        // When CK is high, latch_q holds its value.
    end

    // The gated clock (GCK) is generated by ANDing the input clock (CK)
    // with the stable latched enable (latch_q).
    assign GCK = CK & latch_q;

endmodule
